#include <stdint.h>
#include <stdio.h>
#include <psxgpu.h>
#include <psxgte.h>
#include <psxpad.h>
#include <psxapi.h>
#include <psxetc.h>
#include <psxspu.h>
#include <hwregs_c.h>
#define OT_LEN 8
#define OT_SIZE (1<<OT_LEN)
#define PACKET_LEN 32768
#define GAME_TOP 58
typedef struct{DISPENV disp;DRAWENV draw;uint32_t ot[OT_SIZE];char packets[PACKET_LEN];}DB;
typedef enum{STATE_TITLE,STATE_PLAY,STATE_PAUSE,STATE_DIALOGUE,STATE_GAMEOVER,STATE_ENDING,STATE_CREDITS}GameState;
static DB db[2];static int active=0,font_id;static char*next_packet;static char pad_buffer[2][34];static uint16_t old_btn=0xffff;static GameState state=STATE_TITLE;
static int px=20,py=190,room=0,shards=0,timer_frames=60*60*5,health=3,anim_tick=0,walk_tick=0,facing=1,score=0,checkpoint_room=0,checkpoint_score=0,checkpoint_time=0,last_room=0,area_banner=0;
static uint8_t shard_taken[4]={0},puzzle_done[4]={0},echo_seen[4]={0};static int switch_a=0,switch_b=0,dialogue_id=0,invuln=0;
static void sfx(int p){SPU_CH_VOL_L(0)=0x2200;SPU_CH_VOL_R(0)=0x2200;SPU_CH_FREQ(0)=p;SPU_CH_ADDR(0)=0x200;SPU_CH_ADSR1(0)=0x00ff;SPU_CH_ADSR2(0)=0;SpuSetKey(0,1);SpuSetKey(1,1);}
static void init(void){ResetGraph(0);InitGeom();SpuInit();EnterCriticalSection();InitPAD(pad_buffer[0],34,pad_buffer[1],34);StartPAD();ChangeClearPAD(0);ExitCriticalSection();SetDefDispEnv(&db[0].disp,0,0,320,240);SetDefDrawEnv(&db[0].draw,0,240,320,240);SetDefDispEnv(&db[1].disp,0,240,320,240);SetDefDrawEnv(&db[1].draw,0,0,320,240);db[0].draw.isbg=db[1].draw.isbg=1;setRGB0(&db[0].draw,6,7,15);setRGB0(&db[1].draw,6,7,15);PutDispEnv(&db[0].disp);PutDrawEnv(&db[0].draw);SetDispMask(1);FntLoad(960,0);font_id=FntOpen(8,8,304,54,0,256);ClearOTagR(db[0].ot,OT_SIZE);next_packet=db[0].packets;}
static void rect(int x,int y,int w,int h,int r,int g,int b){TILE*p=(TILE*)next_packet;setTile(p);setXY0(p,x,y);setWH(p,w,h);setRGB0(p,r,g,b);addPrim(db[active].ot,p);next_packet+=sizeof(TILE);}static void frame(void){DrawSync(0);VSync(0);PutDispEnv(&db[active].disp);PutDrawEnv(&db[active].draw);DrawOTag(db[active].ot+OT_SIZE-1);active^=1;ClearOTagR(db[active].ot,OT_SIZE);next_packet=db[active].packets;anim_tick++;if(area_banner>0)area_banner--;}
static uint16_t buttons(void){PADTYPE*p=(PADTYPE*)pad_buffer[0];return p->stat==0?p->btn:0xffff;}static int pressed(uint16_t n,uint16_t k){return !(n&k)&&(old_btn&k);}static int hit(int a,int b,int c,int d,int e,int f,int g,int h){return a<e+g&&a+c>e&&b<f+h&&b+d>f;}static void say(int id){dialogue_id=id;state=STATE_DIALOGUE;}
static void reset_game(void){int i;px=20;py=190;room=0;last_room=0;shards=0;health=3;score=0;timer_frames=60*60*5;switch_a=switch_b=0;invuln=0;area_banner=100;checkpoint_room=0;checkpoint_score=0;checkpoint_time=timer_frames;for(i=0;i<4;i++){shard_taken[i]=0;puzzle_done[i]=0;echo_seen[i]=0;}sfx(0x1200);say(1);}
static void draw_moko(void){int bob=(walk_tick/6)&1;if(invuln>0&&((anim_tick/3)&1))return;rect(px+2,py+2-bob,8,8,232,205,145);rect(px,py+9-bob,12,8,92,76,112);rect(px+2,py+17-bob,3,3,50,45,65);rect(px+7,py+17-bob,3,3,50,45,65);rect(px+(facing?8:3),py+4-bob,2,2,22,20,28);}static void draw_shard(int x,int y){int p=(anim_tick/8)&3;rect(x-2-p,y-5-p,13+p*2,24+p*2,25,75,90);rect(x,y,9,14,80,215,245);rect(x+2,y-4,5,4,190,250,255);rect(x+3,y+3,3,6,230,255,255);}static int hx(void){return 40+((anim_tick*2)%230);}static int hy(void){return 78+(anim_tick%115);}
static void echo_art(void){int p=2+((anim_tick/10)&3);if(room<4&&!echo_seen[room]){int ex=55+room*38,ey=112+room*17;rect(ex-p,ey-p,12+p*2,12+p*2,22,55,75);rect(ex,ey,12,12,95,175,205);rect(ex+4,ey+3,4,6,205,240,245);}}
static void room_art(void){int r=16,g=18,b=32,i;if(room==1){r=26;g=15;b=34;}else if(room==2){r=12;g=28;b=29;}else if(room==3){r=30;g=22;b=12;}else if(room==4){r=25;g=8;b=10;}rect(0,GAME_TOP,320,182,r,g,b);rect(0,222,320,18,42,38,52);for(i=0;i<8;i++)rect((i*47+anim_tick/2)%320,70+((i*29+anim_tick/4)%140),1,1,70,75,100);if(room==0){rect(112,180,18,28,85,100,150);rect(116,185,10,8,180,200,230);}if(room==1){rect(145,176,18,46,170,45,65);rect(220,195,18,27,170,45,65);rect(70,190,14,14,switch_a?60:150,switch_a?210:60,70);rect(270,110,14,14,switch_b?60:150,switch_b?210:60,70);rect(hx(),142,16,8,220,70,80);}if(room==2){rect(125,95,12,127,45,150,115);rect(260,130,12,92,45,150,115);rect(45,82,30,20,70,125,110);rect(190,hy(),8,18,170,220,190);}if(room==3){rect(90,190,45,6,215,130,35);rect(200,110,45,6,215,130,35);rect(150,84,22,22,180,115,35);rect(hx(),160,20,6,240,145,35);}if(room==4){rect(128,82,64,64,90,55,65);rect(144,98,32,32,205,185,120);for(i=0;i<4;i++)if(shard_taken[i])rect(110+i*28,154,12,12,70,200,225);}echo_art();if(room<4&&!shard_taken[room]&&puzzle_done[room])draw_shard(250-room*35,90+room*28);draw_moko();}
static void collect_shard(uint16_t n){int sx,sy;if(room>=4||shard_taken[room]||!puzzle_done[room]||!pressed(n,PAD_CROSS))return;sx=250-room*35;sy=90+room*28;if(hit(px,py,12,18,sx-8,sy-9,25,31)){shard_taken[room]=1;shards++;score+=250;checkpoint_room=room;checkpoint_score=score;checkpoint_time=timer_frames;sfx(0x2400);say(8);}}
static void memory_echo(uint16_t n){int ex,ey;if(room>=4||echo_seen[room]||!pressed(n,PAD_CROSS))return;ex=55+room*38;ey=112+room*17;if(hit(px,py,12,18,ex-10,ey-10,32,32)){echo_seen[room]=1;score+=75;sfx(0x2000);say(10+room);}}
static void interact(uint16_t n){if(!pressed(n,PAD_CROSS))return;memory_echo(n);if(state!=STATE_PLAY)return;if(room==0&&hit(px,py,12,18,105,170,32,45)&&!puzzle_done[0]){puzzle_done[0]=1;score+=100;sfx(0x1800);say(2);return;}if(room==1){if(hit(px,py,12,18,60,180,34,34)&&!switch_a){switch_a=1;score+=50;sfx(0x1000);}if(hit(px,py,12,18,260,100,34,34)&&!switch_b){switch_b=1;score+=50;sfx(0x1400);}if(switch_a&&switch_b&&!puzzle_done[1]){puzzle_done[1]=1;score+=100;sfx(0x1a00);say(3);return;}}if(room==2&&hit(px,py,12,18,35,72,50,40)&&!puzzle_done[2]){if(shards>=2){puzzle_done[2]=1;score+=150;sfx(0x1900);say(4);}else say(7);return;}if(room==3&&hit(px,py,12,18,140,74,42,42)&&!puzzle_done[3]){if(shards>=3){puzzle_done[3]=1;score+=200;sfx(0x1c00);say(5);}else say(7);return;}collect_shard(n);}
static void hurt(void){if(invuln)return;health--;score=score>=25?score-25:0;invuln=60;sfx(0x0700);px=30;py=190;if(health<=0)state=STATE_GAMEOVER;}
static void update_play(uint16_t n){int ox=px,oy=py,m=0;last_room=room;if(!(n&PAD_LEFT)){px-=2;facing=0;m=1;}if(!(n&PAD_RIGHT)){px+=2;facing=1;m=1;}if(!(n&PAD_UP)){py-=2;m=1;}if(!(n&PAD_DOWN)){py+=2;m=1;}if(m)walk_tick++;if(px<0){if(room>0){room--;px=306;sfx(0x0d00);}else px=0;}if(px>308){if(room<4){if(shard_taken[room]){room++;px=2;sfx(0x0d00);}else{px=308;if(pressed(n,PAD_CROSS))say(9);}}else px=308;}if(room!=last_room)area_banner=90;if(py<62)py=62;if(py>204)py=204;if(room==1&&(hit(px,py,12,18,145,176,18,46)||hit(px,py,12,18,220,195,18,27))){px=ox;py=oy;}if(room==2&&(hit(px,py,12,18,125,95,12,127)||hit(px,py,12,18,260,130,12,92))){px=ox;py=oy;}interact(n);if(state!=STATE_PLAY)return;if(invuln>0)invuln--;if(room==1&&hit(px,py,12,18,hx(),142,16,8))hurt();if(room==2&&hit(px,py,12,18,190,hy(),8,18))hurt();if(room==3&&(hit(px,py,12,18,90,184,45,18)||hit(px,py,12,18,hx(),160,20,6)))hurt();if(room==4&&shards==4&&hit(px,py,12,18,125,78,70,72)){score+=timer_frames/60;sfx(0x2800);state=STATE_ENDING;}if(pressed(n,PAD_START))state=STATE_PAUSE;if(timer_frames>0)timer_frames--;else state=STATE_GAMEOVER;}
static void hud(void){static const char*n[]={"SILENT STATION","BACKWARD STREET","HOUSE WITHOUT MORNING","CLOCKWORKS","CLOCK CHAMBER"};int s=timer_frames/60;FntPrint(font_id,"%02d:%02d SHARDS %d/4 HP %d SCORE %d\n%s  CROSS: INTERACT",s/60,s%60,shards,health,score,n[room]);if(area_banner>0){rect(62,76,196,22,5,7,15);FntPrint(font_id,"\n        %s",n[room]);}FntFlush(font_id);}
static void dialogue(void){room_art();rect(12,158,296,70,8,8,18);if(dialogue_id==1)FntPrint(font_id,"The hour was broken. Find what you forgot.");else if(dialogue_id==2)FntPrint(font_id,"The station clock wakes. A memory appears.");else if(dialogue_id==3)FntPrint(font_id,"Both signals glow. A memory is released.");else if(dialogue_id==4)FntPrint(font_id,"Morning returns. Another memory is free.");else if(dialogue_id==5)FntPrint(font_id,"The clockwork core reveals the final shard.");else if(dialogue_id==8)FntPrint(font_id,"MEMORY SHARD RECOVERED. CHECKPOINT SAVED.");else if(dialogue_id==9)FntPrint(font_id,"The way forward is sealed. Recover this memory.");else if(dialogue_id==10)FntPrint(font_id,"ECHO: A platform. A goodbye.\nYou promised you would come back.");else if(dialogue_id==11)FntPrint(font_id,"ECHO: The street ran backward,\nbut you kept walking away.");else if(dialogue_id==12)FntPrint(font_id,"ECHO: Morning never entered this house.\nSomeone was waiting for you.");else if(dialogue_id==13)FntPrint(font_id,"ECHO: The machine did not steal the hour.\nYou asked it to hide one.");else FntPrint(font_id,"Recover the earlier memories first.");FntPrint(font_id,"\nCROSS - continue");FntFlush(font_id);}
int main(void){init();for(;;){uint16_t n=buttons();if(state==STATE_TITLE){rect(0,0,320,240,7,8,20);FntPrint(font_id,"\n\n      M O K O\n   THE LOST HOUR\n\n START - BEGIN\n Find four shards. Remember why.");FntFlush(font_id);if(pressed(n,PAD_START)||pressed(n,PAD_CROSS))reset_game();}else if(state==STATE_PLAY){update_play(n);room_art();hud();}else if(state==STATE_DIALOGUE){dialogue();if(pressed(n,PAD_CROSS))state=STATE_PLAY;}else if(state==STATE_PAUSE){room_art();FntPrint(font_id,"PAUSED  SCORE %d\nSTART - RESUME",score);FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_PLAY;}else if(state==STATE_GAMEOVER){rect(0,0,320,240,24,5,10);FntPrint(font_id,"\n THE HOUR IS LOST\n SCORE %d\n\nCROSS - CHECKPOINT\nSTART - NEW GAME",score);FntFlush(font_id);if(pressed(n,PAD_CROSS)){room=checkpoint_room;px=20;py=190;health=3;score=checkpoint_score;timer_frames=checkpoint_time>60*30?checkpoint_time:60*30;invuln=90;area_banner=90;state=STATE_PLAY;}if(pressed(n,PAD_START))reset_game();}else if(state==STATE_ENDING){rect(0,0,320,240,8,22,28);FntPrint(font_id,"\n THE CLOCK REMEMBERS\n\nMoko did not lose the hour.\nHe buried it to escape a goodbye.\nNow the memory can move again.\n\nFINAL SCORE %d\nCROSS - CREDITS",score);FntFlush(font_id);if(pressed(n,PAD_CROSS))state=STATE_CREDITS;}else{rect(0,0,320,240,5,6,14);FntPrint(font_id,"\n\n MOKO: THE LOST HOUR\n\nOriginal PlayStation homebrew\nPowered by PSn00bSDK\n\nTHE HOUR WAS NEVER LOST.\nIT WAS WAITING.\n\nSTART - TITLE");FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_TITLE;}old_btn=n;frame();}return 0;}
